/* Generated by the Wrapper API.
 *
 * Deliberately minimal: a network-first worker that falls back to a cached
 * shell when offline. An aggressive caching strategy on a site we did not
 * write is how you ship a wrapper that serves stale pages forever.
 */
const CACHE = "com.wrapper.restpilot-v1";
const SHELL = ['index.html', 'manifest.webmanifest', 'icons/icon-192.png'];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  event.respondWith(
    fetch(event.request).catch(() => caches.match(event.request).then((r) => r || caches.match('index.html')))
  );
});
